cd "$ARCHON_HORIZON_ROOT/MainProjects/Algebraic-Jacobian-Challenge" && python3 - <<'PY'
import re, glob, sys
sys.path.insert(0,'/tmp')
from mk_marks import strip_comments, TOK, ENVS
# ALL environments at ANY depth, with their depth
found=[]
for fn in sorted(glob.glob('blueprint/src/chapters/*.tex')):
    t = strip_comments(open(fn).read())
    stack=[]
    for m in TOK.finditer(t):
        kind,name=m.group(1),m.group(2)
        if kind=='begin':
            stack.append((name,m.end(),len(stack)))
        else:
            while stack:
                nm,s,depth=stack.pop()
                if nm==name:
                    if depth>0 and nm in ENVS:
                        body=t[s:m.start()]
                        if '\\lean{' in body and '\\label{' in body:
                            found.append((fn.split('/')[-1],nm,depth,
                                          re.search(r'\\label\{([^}]*)\}',body).group(1),
                                          '\\leanok' in body))
                    break
print('NESTED label+lean envs (invisible to a depth-0 extractor):',len(found))
for x in found: print('   ',x)
PY
